-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per project. A project belongs to one client. Needs project.view.
CREATE VIEW rpt.Project
AS
SELECT
    p.Id AS ProjectId,
    p.ProjectCode AS ProjectCode,
    p.Name AS ProjectName,
    p.ClientId AS ClientId,
    c.Name AS ClientName,
    pt.Name AS ProjectType,
    bt.Name AS BillingType,
    bt.SystemCode AS BillingTypeCode,
    ps.Name AS ProjectStatus,
    ps.SystemCode AS ProjectStatusCode,
    pm.DisplayName AS ProjectManager,
    p.StartDate AS StartDate,
    p.EndDate AS EndDate,
    p.BudgetHours AS BudgetHours,
    CONVERT(DECIMAL(19,2), p.BudgetAmount) AS BudgetAmount,
    CONVERT(DECIMAL(19,2), p.FixedFeeAmount) AS FixedFeeAmount,
    CAST(p.CreatedAt AS DATE) AS CreatedDate
FROM crm.ClientProject AS p
JOIN crm.Client AS c ON c.TenantId = p.TenantId AND c.Id = p.ClientId
JOIN lkp.ProjectType AS pt ON pt.TenantId = p.TenantId AND pt.Id = p.ProjectTypeId
JOIN lkp.BillingType AS bt ON bt.TenantId = p.TenantId AND bt.Id = p.BillingTypeId
JOIN lkp.ProjectStatus AS ps ON ps.TenantId = p.TenantId AND ps.Id = p.ProjectStatusId
LEFT JOIN sec.AppUser AS pm ON pm.TenantId = p.TenantId AND pm.Id = p.ProjectManagerUserId
WHERE p.DeletedAt IS NULL AND EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(p.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'project.view'));
GO
